// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import { addProductToCart, emptyCart } from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:8080");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(60000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(`${baseUrl}/product/OLJCESPC7Z`);
    await addProductToCart(page);
    await expect(page.getByRole("heading", { name: "Order confirmation email" })).toBeVisible();
    await expect(page.locator("#email-preview-panel .preview-total")).toHaveText("$28.98");
    await expect(page.locator("#email-preview-panel .preview-total")).toHaveText(
        await page.locator(".cart-summary-total-row .text-right").innerText());
    await emptyCart(page);
    await page.goto(`${baseUrl}/cart`);
    await expect(page.getByRole("heading", { name: "Your shopping cart is empty!" })).toBeVisible();
    await expect(page.getByTestId("empty-cart")).toBeVisible();
    await expect(page.locator("#email-preview-panel")).toHaveCount(0);
});
